'use strict';
const PROPERTY_UI5={bind,openDialog,cityView,storesView,marketsView,interiorView,help};
TITLES.property='Prostory, nájmy & vlastní budovy';
let propertyCity5='Praha',propertyShow5='network';
const propertyModeName5=s=>s.franchise?'Platí partner':s.premises5.kind==='owned'?'Vlastní budova':s.premises5.enabled?PREMISES_LEASES5[s.premises5.kind].name:'Dosavadní nájem';
function propertyChoices5(value){return Object.entries(PREMISES_LEASES5).map(([k,c])=>option(k,c.name+' · '+c.term+' týdnů · jistota '+c.deposit+'× nájem',value)).join('');}
function propertyQuoteRows5(q,kind){return rows(kind==='buy'?[['Cena budovy',money(q.price)],['Transakční poplatek · 2 %',money(q.fee)],['Vrácená jistota',money(q.refund)],['Hotovost potřebná na koupi',money(q.cost)],['Nájem dnes / údržba po koupi',money(q.rent)+' / '+money(q.upkeep)+' týdně'],['Úspora za prostor / týden',money(q.saving)],['Prostá návratnost',q.payback?q.payback+' týdnů':'Bez úspory']]:kind==='sell'?[['Hrubá prodejní cena',money(q.price)],['Účetní hodnota budovy',money(q.book)],['Výsledek prodeje před poplatky',money(q.gain)],['Poplatky za prodej a smlouvu',money(q.fee+q.leaseFee)],['Nová vratná jistota',money(q.deposit)],['Příjem do hotovosti',money(q.cashChange)],['Nový nájem / týden',money(q.rent)],['Pevná sazba do týdne',state.week+q.term]]:[['Nájem / týden',money(q.rent)],['Pevná sazba do týdne',q.due],['Nová vratná jistota',money(q.deposit)],['Vrácená dosavadní jistota',money(q.refund)],['Předčasné ukončení staré smlouvy',money(q.exit)],['Poplatek za sjednání',money(q.fee)],['Změna hotovosti při podpisu',money(-q.cost)]]);}
function propertyView(){const own=state.stores.filter(s=>!s.franchise),assets=state.property5.assets,last=state.property5.last,total=(a,k)=>a.reduce((n,r)=>n+r[k],0),network=state.stores.filter(s=>propertyCity5==='all'||loc(s.id).city===propertyCity5),free=LOCATIONS.filter(l=>(propertyCity5==='all'||l.city===propertyCity5)&&!owned(l.id)&&!occupant(l.id));return `<div class="view-toolbar"><p class="intro">Porovnej nájem s koupí budovy a hlídej peníze v jistotách. Nájem nebo údržba patří do nákladů kavárny; budova a vratná jistota jsou majetek firmy.</p><button class="soft" id="propertyReport5">Report prostorů</button></div><div class="report-overview5">${metric('VLASTNÍ BUDOVY',assets.length,own.length+' vlastních kaváren')}${metric('HODNOTA BUDOV',money(assets.reduce((n,a)=>n+propertyMarket5(a.location,a.space).value,0)),'Herní odhad; hotovost přijde až při prodeji')}${metric('VRATNÉ JISTOTY',money(own.reduce((n,s)=>n+s.premises5.deposit,0)),'Blokované peníze, nejsou provozní výdaj')}${metric('PROSTORY / POSLEDNÍ TÝDEN',last?money(total(last.rows,'cost')):'—','Nájem a údržba budov tvé firmy')}</div><div class="view-toolbar"><div class="fields">${field('Město',`<select id="propertyCity5">${cityOptions(propertyCity5,true)}</select>`)}${field('Zobrazit',`<select id="propertyShow5">${option('network','Prostory současné sítě',propertyShow5)}${option('free','Volné adresy pro expanzi',propertyShow5)}</select>`)}</div><button class="quiet" data-goto="interior">Vlastní návrhy kaváren</button></div>${propertyShow5==='network'?`<div class="cards">${network.map(s=>{const p=s.premises5,a=propertyAsset5(s.id),m=propertyMarket5(s.id,p.space),r=last?.rows.find(r=>r.id===s.id),cost=s.franchise?0:p.enabled?premisesCost5(s):s.lease.rent;return `<section class="card"><div class="card-head"><div><span class="eyelabel">${esc(loc(s.id).city)}</span><h2>${esc(loc(s.id).name)}</h2></div><span class="badge">${propertyModeName5(s)}</span></div>${rows([['Prostor',PREMISES_SPACES5[p.space].name+(PREMISES_SPACES5[p.space].area?' · '+PREMISES_SPACES5[p.space].area+' m²':'')],['Místa / limit',s.seats+' / '+(p.enabled?PREMISES_SPACES5[p.space].seats:'dle návrhu')],['Nájem nebo údržba / týden',money(cost)],['Vratná jistota',money(p.deposit)],...(a?[['Účetní / tržní hodnota',money(a.book)+' / '+money(m.value)]]:s.franchise?[]:[['Pevná sazba do týdne',s.lease.due],['Zbývá do obnovy',Math.max(0,s.lease.due-state.week)+' týdnů']])])}${r?`<p class="sub">T${r.week} · skutečně započteno ${money(r.cost)} za prostor.</p>`:''}${s.franchise?'<p class="sub">Prostor, jistotu a vybavení spravuje partner. Nájem neplatí tvá firma.</p>':`<div class="actions">${a?`<button class="soft" data-property-action5="sell" data-property-location5="${s.id}" ${state.over?'disabled':''}>Prověřit prodej budovy</button>`:`<button class="primary" data-property-action5="lease" data-property-location5="${s.id}" ${state.over?'disabled':''}>Vybrat smlouvu</button><button class="soft" data-property-action5="buy" data-property-location5="${s.id}" ${state.over?'disabled':''}>Prověřit koupi budovy</button>`}<button class="quiet" data-property-studio5="${s.id}">Návrh kavárny</button></div>${!a?`<label class="checkbox-line"><input type="checkbox" data-property-renew5="${s.id}" ${p.autoRenew?'checked':''} ${state.over?'disabled':''}> Obnovit stejný typ smlouvy, když rezerva dovolí</label>${s.lease.due-state.week<=4?'<p class="property-due5">Blíží se konec sazby. Prověř podmínky nebo pravidlo obnovy.</p>':''}`:''}`}</section>`;}).join('')||empty('V tomto výběru zatím nemáš kavárnu. Vyber Volné adresy pro expanzi a zvol první prostor.')}</div>`:`<section class="card"><h2>Volné adresy</h2><div class="table-scroll"><table class="data property-table5"><thead><tr><th>Adresa / hosté</th><th>Základní otevření</th><th>Nájemní základ</th><th>Odhad ceny budovy</th><th>Další krok</th></tr></thead><tbody>${free.map(l=>{const m=propertyMarket5(l.id);return `<tr><td><strong>${esc(l.name)}</strong><small>${esc(l.city)} · ${SEGMENTS[l.segment].name}</small></td><td>${money(l.setup)}</td><td>${money(m.rent)}/týden</td><td>${money(m.value)}</td><td><button class="soft mini" data-property-open5="${l.id}" ${!unlocked(l.city)||state.over?'disabled':''}>Vybrat prostor</button><small>${!unlocked(l.city)?'Město je zatím uzamčené.':''}</small></td></tr>`}).join('')||'<tr><td colspan="5">V tomto výběru nejsou volné adresy.</td></tr>'}</tbody></table></div></section>`}<section class="card" style="margin-top:24px"><h2>Velikost prostoru</h2><div class="table-scroll"><table class="data"><thead><tr><th>Prostor</th><th>Plocha / místa</th><th>Nájemní základ</th><th>Zájem hostů</th><th>Úprava ceny otevření</th></tr></thead><tbody>${Object.entries(PREMISES_SPACES5).filter(([k])=>k!=='existing').map(([k,s])=>`<tr><td>${s.name}</td><td>${s.area} m² / nejvýše ${s.seats}</td><td>${number(s.rent*100)} %</td><td>${number(s.demand*100)} %</td><td>${s.setup<1?'−':'+'}${number(Math.abs(s.setup-1)*100)} % základu adresy</td></tr>`).join('')}</tbody></table></div><p class="sub">Velikost se volí při otevření. Skutečná poptávka dál závisí na lokalitě, cenách, kvalitě, hostech a konkurenci. Limit míst platí i pro pozdější přestavbu. Původní prostor zachová současné možnosti uložené hry; starší kavárny se automaticky nezmenšují.</p></section><section class="card" style="margin-top:24px"><h2>Poslední změny smluv a budov</h2><div class="table-scroll"><table class="data"><thead><tr><th>Týden / adresa</th><th>Změna</th><th>Změna hotovosti</th><th>Poplatky</th><th>Jistota po změně</th></tr></thead><tbody>${state.property5.events.slice(-16).reverse().map(e=>`<tr><td>T${e.week} · ${esc(loc(e.location).name)}</td><td>${({buy:'Koupě budovy',sell:'Prodej a nový nájem',lease:'Podepsaný nájem',renew:'Obnova smlouvy',rollover:'Přechod na flexibilní nájem'})[e.kind]}</td><td>${money(e.cash)}</td><td>${money(e.fee)}</td><td>${money(e.deposit)}</td></tr>`).join('')||'<tr><td colspan="5">Zatím žádná změna. Starší historii hra nedoplňuje.</td></tr>'}</tbody></table></div><p class="sub">Koupě se ukládá jako majetek, transakční poplatky jako výdaj. Prodej uvolní hotovost a vykáže rozdíl prodejní ceny proti účetní hodnotě; celá prodejní cena není nový zisk. Předčasné ukončení placené nájemní smlouvy stojí polovinu nájmu za nejvýše čtyři zbývající týdny. Po skončení smlouvy je přechod bez sankce. Při koupi vlastní pronajaté budovy se jistota vrací a sankce se neúčtuje.</p></section>`;}
function propertyActionDialog5(kind,id){let lease='standard',quoted;show(`<span class="eyelabel">${esc(loc(id).city)} · ${esc(loc(id).name)}</span><h2>${kind==='buy'?'Koupě vlastní budovy':kind==='sell'?'Prodat budovu, zachovat kavárnu':'Vybrat nájemní smlouvu'}</h2>${kind!=='buy'?field('Typ smlouvy',`<select id="propertyLeaseKind5">${propertyChoices5(lease)}</select>`):''}<div id="propertyQuote5"></div><p class="sub">${kind==='buy'?'Návratnost porovnává jen současný nájem s údržbou. Nezahrnuje budoucí změny trhu, cenu prodeje ani náklady kapitálu. Koupě budovy sama nezvyšuje návštěvnost.':kind==='sell'?'Kavárna zůstane otevřená. Budovu prodáš za 96 % herního tržního odhadu; prodejní poplatek je 2 %. Nová jistota zůstává majetkem firmy.':'Nájem se po dobu smlouvy nezmění. Jistota je vratná; při změně se nejprve započítá její vrácení. Poplatek a případná sankce jsou skutečné výdaje.'}</p><div class="actions"><button class="soft" data-property-preview5="4">Porovnat 4 týdny</button><button class="soft" data-property-preview5="13">Porovnat čtvrtletí</button><button class="primary" id="propertyCommit5" ${state.over?'disabled':''}>Prověřit potvrzení</button></div><div id="propertyComparison5"></div>`);
 const preview=()=>{try{lease=el('propertyLeaseKind5')?.value||'standard';quoted=kind==='buy'?buyPropertyQuote5(id):kind==='sell'?sellPropertyQuote5(id,lease):propertyLeaseQuote5(id,lease);el('propertyQuote5').innerHTML=propertyQuoteRows5(quoted,kind);el('propertyComparison5').innerHTML='';el('propertyCommit5').disabled=state.over||(kind==='sell'?state.cash+quoted.cashChange<0:state.cash<quoted.cost);}catch(e){quoted=null;el('propertyQuote5').textContent=e.message;el('propertyCommit5').disabled=true;}};if(el('propertyLeaseKind5'))el('propertyLeaseKind5').onchange=preview;preview();
 document.querySelectorAll('[data-property-preview5]').forEach(b=>b.onclick=()=>{try{const p=previewProperty5({kind,location:id,lease},Number(b.dataset.propertyPreview5)),sum=(a,k)=>a.reduce((n,h)=>n+h[k],0),a=p.baseline.series,z=p.changed.series,format=n=>money(n);el('propertyComparison5').innerHTML=`<h3>Výhled se změnou a bez ní</h3><div class="table-scroll"><table class="data"><thead><tr><th>Výsledek</th><th>Bez změny</th><th>Po změně</th><th>Rozdíl</th></tr></thead><tbody>${[['Výsledek celé firmy',sum(a,'profit'),sum(z,'profit')],['Hotovost na konci',a.at(-1)?.cash??state.cash,z.at(-1)?.cash??state.cash],['Náklady tohoto prostoru',sum(a,'occupancy'),sum(z,'occupancy')],['Účetní hodnota budov na konci',a.at(-1)?.book??0,z.at(-1)?.book??0],['Jistoty firmy na konci',a.at(-1)?.deposit??0,z.at(-1)?.deposit??0]].map(([name,x,y])=>`<tr><td>${name}</td><td>${format(x)}</td><td>${format(y)}</td><td>${format(y-x)}</td></tr>`).join('')}</tbody></table></div><p class="sub">Obě kopie odehrály skutečnou simulaci se současnými pravidly. Hotovost zahrnuje koupi či prodej, zisk obsahuje jen příslušné výdaje a účetní výsledek prodeje. Rozehraná hra zůstává v T${state.week}. ${p.baseline.over||p.changed.over?'Jedna varianta skončila před koncem období.':''}</p>`;}catch(e){toast(e.message);}});
 el('propertyCommit5').onclick=()=>{if(!quoted)return;const q=quoted,k=lease;confirmAction(kind==='buy'?'Koupit budovu?':kind==='sell'?'Prodat budovu a podepsat nájem?':'Podepsat nájem?',esc(loc(id).name)+' · '+(kind==='sell'?'příjem '+money(q.cashChange)+' po poplatcích a jistotě. Nový nájem '+money(q.rent)+'/týden.':'změna hotovosti '+money(-q.cost)+'. ')+(kind==='buy'?'Údržba '+money(q.upkeep)+'/týden.':kind==='lease'?'Nájem '+money(q.rent)+'/týden; jistota '+money(q.deposit)+'.':''),()=>kind==='buy'?buyProperty5(id,q):kind==='sell'?sellProperty5(id,k,q):signPropertyLease5(id,k,q),kind==='buy'?'Koupit':kind==='sell'?'Prodat a pronajmout':'Podepsat');};}
openDialog=function(id,franchise=false){if(franchise)return PROPERTY_UI5.openDialog(id,true);const l=loc(id);show(`<span class="eyelabel">${esc(l.city.toUpperCase())}</span><h2>Nová kavárna · ${esc(l.name)}</h2><div class="fields">${field('Velikost prostoru',`<select id="openSpace5">${Object.entries(PREMISES_SPACES5).map(([k,s])=>option(k,s.name+(s.area?' · '+s.area+' m² · max. '+s.seats+' míst':''),'existing')).join('')}</select>`)}${field('Smlouva nebo vlastnictví',`<select id="openTenure5">${propertyChoices5('legacy')}${option('owned','Koupit budovu','legacy')}</select>`)}${field('Použít návrh',`<select id="openDesign5">${option('base','Základní kavárna · 24 míst','base')}${state.studio5.designs.map(d=>option(d.id,d.name,'base')).join('')}</select>`)}${field('Značka',`<select id="openBrand">${brandOptions(state.brands[0].id)}</select>`)}${field('Káva',`<select id="openBlend">${blendOptions(state.blends[0].id)}</select>`)}</div><div id="openingPreview5"></div><button class="primary wide" id="openConfirm">Otevřít s tímto návrhem</button>`);let quoted;const read=()=>({kind:el('openTenure5').value,space:el('openSpace5').value}),preview=()=>{try{quoted=openingQuote5(id,el('openDesign5').value,el('openBrand').value,el('openBlend').value,read());const p=quoted.premises;el('openingPreview5').innerHTML=rows([['Adresa a základní vybavení',money(quoted.base)],['Úprava vybavení podle návrhu',money(quoted.changes.cost)],...(p?[['Koupě budovy',money(p.price)],['Vratná jistota',money(p.deposit)],['Poplatek za smlouvu nebo koupi',money(p.fee)],['Nájem / údržba týdně',money(p.rent)+' / '+money(p.upkeep)]]:[]),['Celkem při otevření',money(quoted.cost)],['Zůstane v hotovosti',money(quoted.after)],['Místa / průchodnost',quoted.changes.info.seats+' míst · '+number(quoted.changes.info.flow*100,1)+' %'],['Fixní provoz nové pobočky / týden',money(quoted.weekly)]])+`<div class="studio-open-plan5">${floorSvg5(quoted.design.floor)}</div>`+(quoted.after<(weeklyFixed()+quoted.weekly)*4?'<div class="warning">Po otevření zůstane méně než čtyřtýdenní rezerva fixních nákladů celé firmy.</div>':'')+'<p class="sub">Základní nájem v původním prostoru zachová dosavadní cenu otevření. Nové smlouvy přidají vratnou jistotu. Budova je samostatná investice vedle kavárny a vybavení.</p>';el('openConfirm').disabled=state.over||quoted.after<0;}catch(e){quoted=null;el('openingPreview5').textContent=e.message;el('openConfirm').disabled=true;}};for(const key of ['openDesign5','openBrand','openBlend','openSpace5','openTenure5'])el(key).onchange=preview;preview();el('openConfirm').onclick=()=>{try{if(!quoted)throw Error('Nejdřív vyber platný prostor a návrh.');openStore(id,el('openBrand').value,el('openBlend').value,false,el('openDesign5').value,quoted,read());studioDraft5=null;persist();render();el('modal').close();toast('Kavárna otevřena ve vybraném prostoru.');}catch(e){toast(e.message)}};};
cityView=function(){let html=PROPERTY_UI5.cityView();const s=state.stores.find(s=>s.id===selected&&loc(s.id).city===city);if(s){const cost=s.franchise?'Platí partner':money(s.premises5.enabled?premisesCost5(s):s.lease.rent);html=html.replace('<span>Nájem / týden</span><strong>'+money(loc(s.id).rent)+'</strong>','<span>Nájem nebo údržba / týden</span><strong>'+cost+'</strong>');}return '<div class="actions"><button class="soft" data-goto="property">Porovnat prostory, nájmy a budovy</button></div>'+html;};
storesView=function(){return '<div class="actions"><button class="soft" data-goto="property">Spravovat nájemní smlouvy a vlastní budovy</button></div>'+PROPERTY_UI5.storesView();};
marketsView=function(){const html=PROPERTY_UI5.marketsView(),start=html.indexOf('<section class="card" style="margin-top:24px"><h2>Nájemní smlouvy');return (start>=0?html.slice(0,start):html)+`<section class="card" style="margin-top:24px"><h2>Prostory & vlastní budovy</h2><p class="sub">Nájmy, jistoty, termíny smluv a vlastnictví budov najdeš v samostatné správě prostorů.</p><button class="primary" data-goto="property">Otevřít správu prostorů</button></section>`;};
interiorView=function(){const html=PROPERTY_UI5.interiorView(),s=state.stores.find(s=>s.id===studioTarget5);return (s?.premises5.enabled?`<p class="property-space5">${PREMISES_SPACES5[s.premises5.space].name} · nejvýše ${PREMISES_SPACES5[s.premises5.space].seats} míst. Přestavba musí respektovat velikost prostoru.</p>`:'')+html;};
bind=function(){PROPERTY_UI5.bind();if(el('propertyCity5')){el('propertyCity5').onchange=()=>{propertyCity5=el('propertyCity5').value;render();};el('propertyShow5').onchange=()=>{propertyShow5=el('propertyShow5').value;render();};el('propertyReport5').onclick=()=>{reportKind5='premises';goto('performance');};}on('[data-property-action5]',b=>{try{propertyActionDialog5(b.dataset.propertyAction5,b.dataset.propertyLocation5);}catch(e){toast(e.message);}});on('[data-property-open5]',b=>openDialog(b.dataset.propertyOpen5));on('[data-property-studio5]',b=>{studioTarget5=b.dataset.propertyStudio5;studioDraft5=null;goto('interior');});on('[data-property-renew5]',i=>act(()=>setPropertyRenew5(i.dataset.propertyRenew5,i.checked),'Pravidlo obnovy uloženo.'),'change');};
help=function(){PROPERTY_UI5.help();const p=document.createElement('p');p.textContent='Prostory & budovy: při otevření můžeš zvolit malý, standardní nebo velký prostor, délku nájmu a vlastní budovu. Jistota se ukládá jako vratný majetek; neodečítá zisk. Pevná sazba vydrží do konce smlouvy. Při povolení obnovy a dostatku rezervy se podepíše stejný typ, jinak kavárna pokračuje ve flexibilním nájmu bez dalšího doplatku jistoty. Vlastní budova nahradí nájem údržbou; koupě je investice, poplatek výdaj. Prodej zachová kavárnu v nájmu a zisk změní jen rozdíl proti účetní hodnotě a poplatky. Report firmy má kategorii Prostory & budovy.';el('modalContent').append(p);};el('help').onclick=help;
render();
